-- Stage 11b (4 of 5): open prospect leads into the one pipeline
-- Tom's choices from the review page (https://claude.ai/artifact/DLucB792pjaV87MDs4ufcm), 23 Oct 2026:
-- everything as suggested, except the Formers listed in supabase/.local/11b/choices.txt.
-- Generated by supabase/.local/11b/make_fix.py.
--
-- 2 leads become new businesses (Prospect, Outreach stage "Identified" today, category from the 7,
-- the lead's address, and a note saying where it was found); 2 are linked to the business that
-- already has their name (a business with no Outreach stage and no deal goes to "Identified"); the
-- [TEST] lead is rejected. Each accepted or linked lead points at its business, so it follows the
-- Outreach stage from now on. A name that already exists is never created twice.
-- Every row it changes is copied to cc_phase0_backup (reason 'stage11b_leads_2026_10_24') first.
-- Undo: supabase/data-fixes/20261024_stage11b_4_leads_undo.sql
-- Run with psql -v ON_ERROR_STOP=1 after migration 20261024_001_stage11b. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage11b_leads_2026_10_24') THEN
    RAISE EXCEPTION 'stage11b_leads_2026_10_24 has already been applied';
  END IF;
END $$;

CREATE TEMP TABLE _acc (lead uuid PRIMARY KEY, lead_name text NOT NULL, biz_name text NOT NULL, category text NOT NULL) ON COMMIT DROP;
INSERT INTO _acc VALUES
  ('830810b2-fe7b-42f5-8e70-ff32bbdae3e7', 'The Alchemy Tribe (health food café & gym)', 'The Alchemy Tribe', 'Activities'),
  ('5bf07a15-7618-42e6-ac3f-746c345bf802', 'The White Company', 'The White Company', 'Retail');
CREATE TEMP TABLE _lnk (lead uuid PRIMARY KEY, lead_name text NOT NULL, biz uuid NOT NULL, biz_name text NOT NULL) ON COMMIT DROP;
INSERT INTO _lnk VALUES
  ('d2fe275e-abf9-4fcd-9149-d0160930cd78', 'Doctor Dough Pizza', '11e810c8-e0af-477a-b97c-dac5c5b7f9f6', 'Doctor Dough Pizza'),
  ('1fe709dd-03eb-4722-a265-30b2a760f06f', 'The Chiswick Decorators Ltd', 'ed808538-a26c-4752-b71f-bbfc5bdf66b2', 'The Chiswick Decorators Ltd');
CREATE TEMP TABLE _rej (lead uuid PRIMARY KEY, lead_name text NOT NULL) ON COMMIT DROP;
INSERT INTO _rej VALUES
  ('e00f909c-5f29-4612-a35f-1a18303fd9b0', '[TEST] The Copper Pot Bakery');

-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM _lnk m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(x.lead_name, ', ') INTO bad FROM (
    SELECT lead, lead_name FROM _acc UNION ALL SELECT lead, lead_name FROM _lnk UNION ALL SELECT lead, lead_name FROM _rej) x
  LEFT JOIN prospect_leads l ON l.id = x.lead
  WHERE l.id IS NULL OR l.business_name IS DISTINCT FROM x.lead_name OR l.matched_business_id IS NOT NULL OR l.status = 'rejected';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'lead changed since the review: %', bad; END IF;
    IF (SELECT count(*) FROM organizations) <> 1 THEN RAISE EXCEPTION 'expected one organisation'; END IF;
  -- a business with the new name already exists: link it by hand instead
  SELECT string_agg(a.biz_name, ', ') INTO bad FROM _acc a JOIN businesses b
    ON lower(regexp_replace(b.name, '[^a-zA-Z0-9]', '', 'g')) = lower(regexp_replace(a.biz_name, '[^a-zA-Z0-9]', '', 'g'))
   AND b.merged_into IS NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'already a business with this name: %', bad; END IF;
END $$;

INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'prospect_leads', l.id, to_jsonb(l), 'stage11b_leads_2026_10_24' FROM prospect_leads l
WHERE l.id IN (SELECT lead FROM _acc UNION SELECT lead FROM _lnk UNION SELECT lead FROM _rej);
INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', b.id, to_jsonb(b), 'stage11b_leads_2026_10_24' FROM businesses b WHERE b.id IN (SELECT biz FROM _lnk);

-- new businesses (backed up with a 'created' marker: undo removes them)
CREATE TEMP TABLE _made (lead uuid, biz uuid) ON COMMIT DROP;
WITH made AS (
  INSERT INTO businesses (name, normalized_name, category, status, address, organization_id, notes,
    outreach_stage, outreach_identified_at)
  SELECT a.biz_name, lower(a.biz_name), a.category, 'Prospect', l.address, (SELECT o.id FROM organizations o ORDER BY o.created_at LIMIT 1),
    'From a prospect lead found ' || to_char(l.found_at, 'DD/MM/YYYY') || coalesce(' on ' || l.source_name, '')
      || coalesce(' (' || l.source_url || ')', '') || ': ' || l.business_name
      || coalesce(E'\n' || nullif(btrim(l.snippet), ''), '') || coalesce(E'\n' || nullif(btrim(l.opportunity_notes), ''), ''),
    'identified', public.cc_today()
  FROM _acc a JOIN prospect_leads l ON l.id = a.lead
  RETURNING id, name
)
INSERT INTO _made SELECT a.lead, m.id FROM made m JOIN _acc a ON a.biz_name = m.name;
INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', biz, jsonb_build_object('stage11b', 'created'), 'stage11b_leads_2026_10_24' FROM _made;

UPDATE prospect_leads l SET matched_business_id = m.biz, match_type = 'new_business' FROM _made m WHERE l.id = m.lead;

UPDATE prospect_leads l SET matched_business_id = k.biz,
  match_type = CASE WHEN v.deal_state = 'none' THEN 'existing_no_deal' WHEN v.deal_state = 'ended' THEN 'existing_expired' ELSE l.match_type END
FROM _lnk k JOIN v_businesses v ON v.id = k.biz WHERE l.id = k.lead;

UPDATE businesses b SET outreach_stage = 'identified', outreach_identified_at = public.cc_today()
FROM _lnk k JOIN v_businesses v ON v.id = k.biz
WHERE b.id = k.biz AND b.outreach_stage IS NULL AND v.deal_state = 'none';

UPDATE prospect_leads l SET status = 'rejected' FROM _rej r WHERE l.id = r.lead;

DO $$ BEGIN
  IF (SELECT count(*) FROM _made) <> (SELECT count(*) FROM _acc) THEN RAISE EXCEPTION 'check failed: businesses not made'; END IF;
  RAISE NOTICE 'stage 11b leads: % new businesses, % linked, % rejected', (SELECT count(*) FROM _made), (SELECT count(*) FROM _lnk), (SELECT count(*) FROM _rej);
END $$;

COMMIT;
